<?php
/**  * Check current status of all service types  */  require_once __DIR__ . '/lib.php';
require_once __DIR__ . '/../public/db_connect.php';  try {  $stmt = $pdo->query("SELECT id, service_name, status, active FROM job_order_service_types ORDER BY service_name");  $services = $stmt->fetchAll(PDO::FETCH_ASSOC);  echo "Current Service Type Status:\n";  echo str_repeat("=", 80) . "\n";  printf("%-5s | %-30s | %-10s | %-6s\n", "ID", "Service Name", "Status", "Active");  echo str_repeat("-", 80) . "\n";  foreach ($services as $svc) {  printf("%-5s | %-30s | %-10s | %-6s\n",  $svc['id'],  $svc['service_name'],  $svc['status'],  $svc['active']  );  }  echo str_repeat("=", 80) . "\n";  echo "Total: " . count($services) . " service type(s)\n";  } catch (Exception $e) {  echo "ERROR: " . $e->getMessage() . "\n";
}
